<?php
declare(strict_types=1); require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/functions.php'; require_login(); $error='';$events=$pdo->query('SELECT event_id,event_name FROM events ORDER BY event_date DESC')->fetchAll();$participants=$pdo->query("SELECT participant_id,CONCAT(first_name,' ',last_name) AS participant_name FROM participants ORDER BY last_name,first_name")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';$id=filter_input(INPUT_POST,'registration_id',FILTER_VALIDATE_INT);try{if($a==='save'){$event=filter_input(INPUT_POST,'event_id',FILTER_VALIDATE_INT);$participant=filter_input(INPUT_POST,'participant_id',FILTER_VALIDATE_INT);$date=$_POST['registration_date']??date('Y-m-d');$status=$_POST['status']??'Registered';if(!$event||!$participant||!in_array($status,['Registered','Attended','Cancelled'],true))throw new InvalidArgumentException('Select a valid event, participant, and status.');if($id){$s=$pdo->prepare('UPDATE registrations SET event_id=?,participant_id=?,registration_date=?,status=? WHERE registration_id=?');$s->execute([$event,$participant,$date,$status,$id]);flash('success','Registration updated successfully.');}else{$s=$pdo->prepare('INSERT INTO registrations(event_id,participant_id,registration_date,status) VALUES(?,?,?,?)');$s->execute([$event,$participant,$date,$status]);flash('success','Registration added successfully.');}}elseif($a==='delete'&&$id){$s=$pdo->prepare('DELETE FROM registrations WHERE registration_id=?');$s->execute([$id]);flash('success','Registration deleted successfully.');}redirect('/event_shit/registrations/registrations.php');}catch(InvalidArgumentException $x){$error=$x->getMessage();}catch(PDOException $x){$error=$x->getCode()==='23000'?'Participant is already registered for this event.':'Unable to complete the registration operation.';}}$q=trim((string)($_GET['search']??''));$s=$pdo->prepare("SELECT r.*,e.event_name,CONCAT(p.first_name,' ',p.last_name) AS participant_name FROM registrations r JOIN events e ON e.event_id=r.event_id JOIN participants p ON p.participant_id=r.participant_id WHERE e.event_name LIKE ? OR p.first_name LIKE ? OR p.last_name LIKE ? ORDER BY r.registration_date DESC");$t="%$q%";$s->execute([$t,$t,$t]);$rows=$s->fetchAll();$pageTitle='Registrations';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/sidebar.php';
?><main class="col-md-9 col-lg-10 p-4"><?php require __DIR__.'/../includes/alerts.php';if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="d-flex justify-content-between mb-4"><h1 class="h3">Registrations</h1><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#edit">+ Add registration</button></div><form class="row g-2 mb-3"><div class="col-sm-6"><input class="form-control" name="search" value="<?=e($q)?>" placeholder="Search event or participant"></div><div class="col-auto"><button class="btn btn-outline-secondary">Search</button></div></form><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>ID</th><th>Event</th><th>Participant</th><th>Date</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['registration_id']?></td><td><?=e($r['event_name'])?></td><td><?=e($r['participant_name'])?></td><td><?=e($r['registration_date'])?></td><td><span class="badge text-bg-light"><?=e($r['status'])?></span></td><td class="text-end"><button class="btn btn-sm btn-outline-primary" data-bs-toggle="modal" data-bs-target="#edit" data-id="<?=$r['registration_id']?>" data-event="<?=$r['event_id']?>" data-participant="<?=$r['participant_id']?>" data-date="<?=$r['registration_date']?>" data-status="<?=e($r['status'])?>">Edit</button><button class="btn btn-sm btn-outline-danger" data-bs-toggle="modal" data-bs-target="#delete" data-id="<?=$r['registration_id']?>" data-name="<?=e($r['event_name'].' / '.$r['participant_name'])?>">Delete</button></td></tr><?php endforeach;?></tbody></table></div></div></main><div class="modal fade" id="edit"><div class="modal-dialog"><form class="modal-content" method="post"><div class="modal-header"><h2 class="modal-title fs-5">Registration</h2><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="modal-body"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="registration_id" id="registration_id"><label class="form-label">Event</label><select class="form-select mb-3" name="event_id" id="event_id" required><?php foreach($events as $v):?><option value="<?=$v['event_id']?>"><?=e($v['event_name'])?></option><?php endforeach;?></select><label class="form-label">Participant</label><select class="form-select mb-3" name="participant_id" id="participant_id" required><?php foreach($participants as $v):?><option value="<?=$v['participant_id']?>"><?=e($v['participant_name'])?></option><?php endforeach;?></select><label class="form-label">Registration date</label><input class="form-control mb-3" type="date" name="registration_date" id="registration_date" required><label class="form-label">Status</label><select class="form-select" name="status" id="status"><?php foreach(['Registered','Attended','Cancelled'] as $v):?><option><?=$v?></option><?php endforeach;?></select></div><div class="modal-footer"><button class="btn btn-primary">Save</button></div></form></div></div><div class="modal fade" id="delete"><div class="modal-dialog"><form class="modal-content" method="post"><div class="modal-header"><h2 class="modal-title fs-5">Confirm delete</h2><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="modal-body">Delete <strong id="dn"></strong>?<input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="registration_id" id="di"></div><div class="modal-footer"><button class="btn btn-secondary" data-bs-dismiss="modal" type="button">Cancel</button><button class="btn btn-danger">Delete</button></div></form></div></div><script>edit.addEventListener('show.bs.modal',e=>{let b=e.relatedTarget;[['id','registration_id'],['event','event_id'],['participant','participant_id'],['date','registration_date'],['status','status']].forEach(x=>document.getElementById(x[1]).value=b.dataset[x[0]]||'')});delete.addEventListener('show.bs.modal',e=>{let b=e.relatedTarget;di.value=b.dataset.id;dn.textContent=b.dataset.name});</script><?php require __DIR__.'/../includes/footer.php';?>
